//
//	client.OAuthFlow.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(oauthflow.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *OAuthFlowUpsertBulk) UpdateNewValues() *OAuthFlowUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(oauthflow.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(oauthflow.FieldCreatedAt)
			}
			if _, exists := b.mutation.Provider(); exists {
				s.SetIgnore(oauthflow.FieldProvider)
			}
			if _, exists := b.mutation.Purpose(); exists {
				s.SetIgnore(oauthflow.FieldPurpose)
			}
			if _, exists := b.mutation.StateHash(); exists {
				s.SetIgnore(oauthflow.FieldStateHash)
			}
			if _, exists := b.mutation.PreSessionID(); exists {
				s.SetIgnore(oauthflow.FieldPreSessionID)
			}
			if _, exists := b.mutation.SessionID(); exists {
				s.SetIgnore(oauthflow.FieldSessionID)
			}
			if _, exists := b.mutation.RedirectURI(); exists {
				s.SetIgnore(oauthflow.FieldRedirectURI)
			}
			if _, exists := b.mutation.PkceVerifierCiphertext(); exists {
				s.SetIgnore(oauthflow.FieldPkceVerifierCiphertext)
			}
			if _, exists := b.mutation.KeyID(); exists {
				s.SetIgnore(oauthflow.FieldKeyID)
			}
			if _, exists := b.mutation.ExpiresAt(); exists {
				s.SetIgnore(oauthflow.FieldExpiresAt)
			}
		}
	}))
	return u
}

